<?php
namespace App\Services\Marketing;
use App\Jobs\ProcessMarketingSemanticOptimization;use App\Models\{MarketingAiRun,MarketingProject,MarketingVideoFilm};use Illuminate\Support\Facades\{DB,Cache,Storage};use Illuminate\Support\Str;
class MarketingSemanticOptimization {
 public const ACTION='film_semantic_opt';
 public function start(string $project,int $owner,string $film,string $hash,string $request):MarketingAiRun {
  abort_unless(MarketingEditingConversation::enabled(),403);$base=app(MarketingOptimization::class)->film($project,$owner,$film);abort_unless(hash_equals($base->output_sha256,$hash),409,'来源已变化。');$identity=app(MarketingSemanticEvidence::class)->identity($base);
  return DB::transaction(function()use($project,$owner,$base,$identity,$request){MarketingProject::whereKey($project)->lockForUpdate()->firstOrFail();$q=MarketingAiRun::where('project_id',$project)->where('action',self::ACTION);$byRequest=(clone $q)->where('usage->client_request_id',$request)->first();if($byRequest)abort_unless(($byRequest->usage['identity']['digest']??'')===$identity['digest'],409,'请求已用于其他来源。');$old=(clone $q)->where('usage->identity->digest',$identity['digest'])->latest()->first();if($old)return $old;
   $r=MarketingAiRun::create(['project_id'=>$project,'request_id'=>(string)Str::uuid(),'action'=>self::ACTION,'status'=>'queued','usage'=>['owner_id'=>$owner,'film_id'=>$base->id,'base_hash'=>$base->output_sha256,'identity'=>$identity,'client_request_id'=>$request,'model'=>MarketingOptimizationClient::MODEL,'stage'=>'queued','provider_attempts'=>0,'automatic_retry'=>false,'one_click'=>['status'=>'queued','adoption_id'=>(string)Str::uuid(),'error'=>null],'publication_authorized'=>false]]);ProcessMarketingSemanticOptimization::dispatch($r->id);return $r;
  });
 }
 private function state(MarketingAiRun $run,array $data,?string $status=null):void {DB::transaction(function()use($run,$data,$status){$r=MarketingAiRun::lockForUpdate()->findOrFail($run->id);$u=array_replace($r->usage,$data);$r->update(['usage'=>$u]+($status?['status'=>$status]:[]));});$run->refresh();}
 private function base(MarketingAiRun $r):MarketingVideoFilm {$f=app(MarketingOptimization::class)->film($r->project_id,$r->usage['owner_id'],$r->usage['film_id']);abort_unless(hash_equals($r->usage['identity']['digest'],app(MarketingSemanticEvidence::class)->identity($f)['digest']),409,'成片或事实已变化。');return $f;}
 public function process(string $id):void {
  $lock=Cache::lock('semantic-optimization:'.$id,1200);if(!$lock->get())return;$called=false;
  try{$r=MarketingAiRun::findOrFail($id);if($r->action!==self::ACTION||$r->status!=='queued')return;if($r->updated_at->lt(now()->subMinutes(20))){$this->interrupt($id);return;}$this->state($r,['stage'=>'sampling'],'running');$base=$this->base($r);$e=app(MarketingSemanticEvidence::class)->collect($base,$id);
   $disk=Storage::disk('local');$file='marketing-semantic/'.$id.'/evidence.json';if(!$disk->exists($file))$disk->put($file,json_encode($e,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));$this->state($r,['sample_count'=>count($e['samples']),'evidence_path'=>$file,'evidence_sha256'=>hash_file('sha256',$disk->path($file)),'stage'=>'analysis']);
   DB::transaction(function()use($r){$locked=MarketingAiRun::lockForUpdate()->findOrFail($r->id);abort_unless(($locked->usage['provider_attempts']??0)===0,409);$u=$locked->usage;$u['provider_attempts']=1;$u['request_claimed_at']=now()->toIso8601String();$locked->update(['usage'=>$u]);});$called=true;$r->refresh();
   $result=app(MarketingSemanticClient::class)->inspect($e);$this->state($r,['raw_answer'=>$result['answer'],'provider_usage'=>$result['usage'],'response_id'=>$result['response_id'],'response_model'=>$result['model'],'stage'=>'validating']);$this->finish($r,$e,$result['answer']);
  }catch(\Throwable $err){if(isset($r)){$click=$r->usage['one_click'];$click['status']='failed';$click['error']='语义优化未完成，原版保留；没有自动重试分析。';$this->state($r,['stage'=>$called?'unknown':'failed','one_click'=>$click,'error_type'=>class_basename($err),'automatic_retry'=>false],$called?'unknown':'failed');}report($err);}finally{$lock->release();}
 }
 private function finish(MarketingAiRun $r,array $e,array $answer):void {
  $base=$this->base($r);$compiled=app(MarketingSemanticCompiler::class)->compile($base,$e,$answer);
  $compiled=app(MarketingSemanticGeometry::class)->audit($base,$compiled,$r->id);$click=$r->usage['one_click'];if(!$compiled['applied']){$click['status']='unchanged';$this->state($r,['stage'=>'completed','compiled'=>$compiled,'one_click'=>$click],'completed');return;}
  $s=$compiled['state'];$proof=MarketingSemanticProof::seal($compiled['provenance']+['evidence_path'=>$r->usage['evidence_path'],'evidence_sha256'=>$r->usage['evidence_sha256']]);
  DB::transaction(function()use($r,$base,$s,$proof,$compiled,$click){$new=app(MarketingFilmPackaging::class)->prepare($base->project_id,$base->owner_id,$click['adoption_id'],$base->id,$base->output_sha256,$s['settings'],null,$s['information_cards'],$s['framing'],$s['emphasis'],$s['overlays'],$s['speed'],true,$proof);$result=$new->result??[];$result['ai_optimization']=['run_id'=>$r->id,'contract'=>MarketingSemanticEvidence::VERSION,'source_film_id'=>$base->id,'source_sha256'=>$base->output_sha256,'applied'=>$compiled['applied'],'skipped'=>$compiled['skipped']];$new->update(['result'=>$result]);$click['status']='rendering';$click['film_id']=$new->id;$click['error']=null;$this->state($r,['stage'=>'completed','compiled'=>$compiled,'one_click'=>$click],'completed');});
 }
 /** Only cached successful provider output is recompiled; this method never calls a model. */
 public function resumeCached(string $id):void {$r=MarketingAiRun::where('action',self::ACTION)->findOrFail($id);abort_unless(isset($r->usage['raw_answer'],$r->usage['evidence_path'])&&!isset($r->usage['one_click']['film_id']),409);$path=app(MarketingVideoFiles::class)->file($r->usage['evidence_path'],$r->usage['evidence_sha256']);$e=json_decode(file_get_contents($path),true,64,JSON_THROW_ON_ERROR);$this->finish($r,$e,$r->usage['raw_answer']);}
 public function interrupt(string $id):void {$r=MarketingAiRun::where('action',self::ACTION)->find($id);if(!$r||isset($r->usage['one_click']['film_id'])||in_array($r->status,['completed','failed','unknown']))return;$click=$r->usage['one_click'];$click['status']='failed';$click['error']='后台任务中断，原版保留；没有重试收费分析。';$this->state($r,['stage'=>'unknown','one_click'=>$click],'unknown');}
 public function read(string $project,int $owner,string $film,?string $runId=null):?MarketingAiRun {$base=app(MarketingOptimization::class)->film($project,$owner,$film);$identity=app(MarketingSemanticEvidence::class)->identity($base);$q=MarketingAiRun::where('project_id',$project)->where('action',self::ACTION);$r=$runId?$q->findOrFail($runId):$q->where('usage->identity->digest',$identity['digest'])->latest()->first();if($r)abort_unless(($r->usage['owner_id']??null)===$owner&&($r->usage['film_id']??'')===$film&&hash_equals($r->usage['identity']['digest'],$identity['digest']),409);return $r;}
 public function present(?MarketingAiRun $r):?array {if(!$r)return null;$u=$r->usage;$click=$u['one_click'];$one=['status'=>$click['status'],'film_id'=>$click['film_id']??null,'error'=>$click['error']??null,'url'=>null];if($one['film_id']){$f=MarketingVideoFilm::where('project_id',$r->project_id)->where('owner_id',$u['owner_id'])->findOrFail($one['film_id']);$one['status']=match($f->status){'completed'=>'completed','failed','unknown'=>'failed',default=>'rendering'};$one['error']=$f->error_message;$one['url']=route('marketing.workspace.show',['project'=>$r->project_id,'screen'=>'finished','film'=>$f->id]);}elseif($r->updated_at->lt(now()->subMinutes(20))&&in_array($one['status'],['queued','applying'])){$one['status']='failed';$one['error']='优化任务已中断，原版保留。';}return ['id'=>$r->id,'status'=>$r->status,'stage'=>$u['stage'],'model'=>$u['model'],'base_film_id'=>$u['film_id'],'base_hash'=>$u['base_hash'],'error'=>$one['error'],'sample_count'=>$u['sample_count']??0,'one_click'=>$one,'automatic_retry'=>false];}
 public function assertFilm(MarketingVideoFilm $film):void {$proof=$film->input['semantic']??null;if(!$proof)return;abort_unless(is_array($proof)&&MarketingSemanticProof::valid($proof),409,'语义配方凭据无效。');app(MarketingSemanticFacts::class)->assertFresh($film,$proof['facts']);app(MarketingVideoFiles::class)->file($proof['evidence_path'],$proof['evidence_sha256']);$source=MarketingVideoFilm::where('project_id',$film->project_id)->where('owner_id',$film->owner_id)->findOrFail($proof['source_film_id']);app(MarketingVideoFiles::class)->file($source->output_path,$proof['source_sha256']);}
}
